# Function to calculate the number of independent sets in a Path Graph P_N
# This is equivalent to F_{N+2} where F_1=1, F_2=1
def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1 or n == 2:
        return 1
    a, b = 1, 1
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

def count_independent_sets_path(N):
    # For a path graph P_N, the number of independent sets is F_{N+2}
    # We need F_{N+2}
    return fibonacci(N + 2)

# Calculate for N=4 and N=7
